-- =====================================================================================
-- SubscriptIQ shared DEMO data  (safe to re-run)
--
--  * DEMO / TEST DATA ONLY. Never run this against production.
--  * Realistic fictional businesses, people and billing history so every module can be tried
--    with data that behaves like a real company (price rises, seat changes, late payers,
--    failed / pending / refunded payments, overdue invoices ...).
--  * Idempotent: every row has a fixed id (de00000X-0000-4000-8000-...) and is inserted with
--    ON CONFLICT DO NOTHING, so running it again creates no duplicates. Demo invoices,
--    subscriptions and quotations are numbered INV-DEMO-###, SUB-DEMO-##, QUO-DEMO-##.
--  * It never updates or deletes rows that are not demo rows. The only existing rows it
--    touches are the profiles of the 5 demo login e-mails below (name, role) and, for the 3 demo
--    customer users, the link customers.user_id. Your own admin account is NOT touched: records
--    are attributed to the oldest admin profile.
--  * No passwords, tokens or keys are stored here. All e-mail addresses use example.com, which
--    can never receive mail. Create the 5 demo users yourself first
--    (Supabase dashboard -> Authentication -> Users -> Add user, "Auto Confirm User" ON):
--        meera.menon@subscriptiq.example.com       -> staff    (Meera Menon, Billing Executive)
--        rahul.varma@subscriptiq.example.com       -> staff    (Rahul Varma, Account Manager)
--        priya.nair@aaravtextiles.example.com      -> customer, linked to Aarav Textiles
--        anil.thomas@keralaspice.example.com       -> customer, linked to Kerala Spice Co
--        divya.ramesh@niladigital.example.com      -> customer, linked to Nila Digital Studio
--    The data loads even if the users do not exist yet; run the script again after creating
--    them to apply the names, roles and links.
--  * Run it in the Supabase SQL editor (runs as the database owner, so it is not blocked by
--    Row Level Security; the data itself is built to be visible through RLS as designed).
--  * Dates are relative to the day you FIRST run it (last 12 months), so charts look current.
--  * Run the migrations 1-6 first (the billing migrations after that are optional for the data).
-- =====================================================================================
begin;

-- ---------------------------------------------------------------- customers (12)
on conflict do nothing;

-- ------------------------------------------------------------ products (7) and plans (9)
on conflict do nothing;

on conflict do nothing;

-- ------------------------------------------------------------- subscriptions (12)
on conflict do nothing;

on conflict do nothing;

-- --------------------------------------------------------------- quotations (6)
on conflict do nothing;

on conflict do nothing;

-- ------------------------------------------------------------------ invoices (67)
-- status / amount_paid / paid_at are the final values; the payments inserted below produce the same numbers through the database trigger.
on conflict do nothing;

on conflict do nothing;

-- ----------------------------------------------------------------- payments (67)
-- ONE statement on purpose: the invoice-sync trigger then sees all payments of an invoice together.
on conflict do nothing;

-- ------------------------------------------------------ names, roles and links for the demo logins
-- Only the five demo e-mails are touched. Skipped silently if a user has not been created yet.
update public.profiles set role = 'staff', full_name = 'Meera Menon' where email = 'meera.menon@subscriptiq.example.com' and (role <> 'staff' or full_name = split_part(email, '@', 1));
update public.profiles set role = 'staff', full_name = 'Rahul Varma' where email = 'rahul.varma@subscriptiq.example.com' and (role <> 'staff' or full_name = split_part(email, '@', 1));

update public.profiles set full_name = 'Priya Nair' where email = 'priya.nair@aaravtextiles.example.com' and full_name = split_part(email, '@', 1);
update public.customers c set user_id = p.id from public.profiles p
 where p.email = 'priya.nair@aaravtextiles.example.com' and c.id = 'de000001-0000-4000-8000-000000000001' and c.user_id is null
   and not exists (select 1 from public.customers x where x.user_id = p.id);
update public.profiles set full_name = 'Anil Thomas' where email = 'anil.thomas@keralaspice.example.com' and full_name = split_part(email, '@', 1);
update public.customers c set user_id = p.id from public.profiles p
 where p.email = 'anil.thomas@keralaspice.example.com' and c.id = 'de000001-0000-4000-8000-000000000002' and c.user_id is null
   and not exists (select 1 from public.customers x where x.user_id = p.id);
update public.profiles set full_name = 'Divya Ramesh' where email = 'divya.ramesh@niladigital.example.com' and full_name = split_part(email, '@', 1);
update public.customers c set user_id = p.id from public.profiles p
 where p.email = 'divya.ramesh@niladigital.example.com' and c.id = 'de000001-0000-4000-8000-000000000003' and c.user_id is null
   and not exists (select 1 from public.customers x where x.user_id = p.id);

-- ----------------------------------------------------------------------- self-check
-- Aborts (and rolls the whole script back) if the demo numbers are not internally consistent.
do $$
declare bad integer; n_cust integer; n_inv integer; n_pay integer; n_sub integer; users integer;
begin
  select count(*) into bad from public.invoices i
   where i.id::text like 'de000008-%'
     and (i.total <> i.subtotal - i.discount_total + i.tax_total
          or i.amount_paid <> coalesce((select sum(amount) from public.payments p where p.invoice_id = i.id and p.status = 'succeeded'), 0)
          or i.total <> coalesce((select sum(line_total) from public.invoice_items it where it.invoice_id = i.id), 0)
          or i.subtotal - i.discount_total + i.tax_total <> coalesce((select sum(quantity * unit_price) - sum(discount_amount) + sum(tax_amount) from public.invoice_items it where it.invoice_id = i.id), 0));
  if bad > 0 then raise exception 'Demo seed self-check failed: % invoice(s) have inconsistent totals or paid amounts', bad; end if;

  select count(*) into n_cust from public.customers where id::text like 'de000001-%';
  select count(*) into n_sub  from public.subscriptions where id::text like 'de000004-%';
  select count(*) into n_inv  from public.invoices where id::text like 'de000008-%';
  select count(*) into n_pay  from public.payments where id::text like 'de00000a-%';
  select count(*) into users  from public.profiles where email in (
    'meera.menon@subscriptiq.example.com', 'rahul.varma@subscriptiq.example.com',
    'priya.nair@aaravtextiles.example.com', 'anil.thomas@keralaspice.example.com', 'divya.ramesh@niladigital.example.com');
  raise notice 'Demo data present: % customers, % subscriptions, % invoices, % payments. Demo login accounts found: % of 5.', n_cust, n_sub, n_inv, n_pay, users;
  if users < 5 then raise notice 'Create the missing demo users in Authentication -> Users, then run this script again to apply names, roles and links.'; end if;
end $$;

commit;
